package dominoes

// Domino represents a single domino stone with two halves.
type Domino [2]int

// MakeChain returns a way to order the given dominoes so that they form a
// closed chain: adjacent halves match and the two exposed ends match each
// other. The second return value reports whether such a chain exists.
func MakeChain(input []Domino) ([]Domino, bool) {
	if len(input) == 0 {
		return []Domino{}, true
	}

	used := make([]bool, len(input))
	chain := make([]Domino, 0, len(input))

	// Seed the chain with each domino in each possible orientation.
	for i := 0; i < len(input); i++ {
		for _, d := range []Domino{input[i], flip(input[i])} {
			used[i] = true
			chain = append(chain, d)
			if backtrack(input, used, chain, d[1]) {
				return chain, true
			}
			chain = chain[:len(chain)-1]
			used[i] = false
		}
	}

	return nil, false
}

// backtrack extends the current chain (whose open end is `end`) with any
// unused domino whose matching half equals `end`, trying both orientations.
// It succeeds once every domino has been placed and the chain closes back
// onto the value that started it.
func backtrack(input []Domino, used []bool, chain []Domino, end int) bool {
	if len(chain) == len(input) {
		return chain[0][0] == end
	}

	for i := 0; i < len(input); i++ {
		if used[i] {
			continue
		}
		d := input[i]

		if d[0] == end {
			used[i] = true
			chain = append(chain, d)
			if backtrack(input, used, chain, d[1]) {
				return true
			}
			chain = chain[:len(chain)-1]
			used[i] = false
		}

		if d[1] == end && d[0] != d[1] {
			used[i] = true
			chain = append(chain, flip(d))
			if backtrack(input, used, chain, d[0]) {
				return true
			}
			chain = chain[:len(chain)-1]
			used[i] = false
		}
	}

	return false
}

func flip(d Domino) Domino {
	return Domino{d[1], d[0]}
}

