	if len(input) == 0 {
		return []Domino{}, true
	}

	used := make([]bool, len(input))
	chain := make([]Domino, 0, len(input))

	// Seed the chain with each domino in each possible orientation.
	for i := 0; i < len(input); i++ {
		for _, d := range []Domino{input[i], flip(input[i])} {
			used[i] = true
			chain = append(chain, d)
			if backtrack(input, used, &chain, d[1]) {
				return chain, true
			}
			chain = chain[:len(chain)-1]
			used[i] = false
		}
	}

