// backtrack extends the current chain (whose open end is `end`) with any
// unused domino whose matching half equals `end`, trying both orientations.
// It succeeds once every domino has been placed and the chain closes back
// onto the value that started it. The chain is passed by pointer so that
// appends made in deeper frames are visible to the caller.
func backtrack(input []Domino, used []bool, chain *[]Domino, end int) bool {
	if len(*chain) == len(input) {
		return (*chain)[0][0] == end
	}

	for i := 0; i < len(input); i++ {
		if used[i] {
			continue
		}
		d := input[i]

		if d[0] == end {
			used[i] = true
			*chain = append(*chain, d)
			if backtrack(input, used, chain, d[1]) {
				return true
			}
			*chain = (*chain)[:len(*chain)-1]
			used[i] = false
		}

		if d[1] == end && d[0] != d[1] {
			used[i] = true
			*chain = append(*chain, flip(d))
			if backtrack(input, used, chain, d[0]) {
				return true
			}
			*chain = (*chain)[:len(*chain)-1]
			used[i] = false
		}
	}

	return false
}

func flip(d Domino) Domino {
	return Domino{d[1], d[0]}
}

